import asyncio
import math
import struct
import typing

from jsilib.aio.exc import StreamClosedError
from jsilib.transport.frames import Chunk, Ack, Nack

from . import exc as jsi_exc
from .interface import IJSIMessage


class JSISwimIncomingMessage(IJSIMessage):
    """Incoming message for SWIM compatibility mode connection.

    :param message_id:
        Incoming message ID.

    :param swim_message_size:
        Message size (in bytes) as sent by SWIM.

        Includes additional 4 bytes for each non-first chunk.

    :param swim_chunk_size:
        Chunk size (in bytes) as received from SWIM.

        The size of first received chunk is used here.
    """

    def __init__(self,
                 message_id: int,
                 swim_message_size: int,
                 swim_chunk_size: int,
                 header_size: int):
        number_of_chunks = 1\
            if swim_chunk_size == 0 or swim_message_size == 0\
            else math.ceil(swim_message_size / swim_chunk_size)
        self._message_id = message_id
        self._swim_message_size = swim_message_size
        self._real_message_size = swim_message_size - (number_of_chunks - 1) * (header_size + 4)
        self._bytes_left = self._real_message_size
        self._chunk_queue: asyncio.Queue[Chunk] = asyncio.Queue()
        self._completion_handler = None
        self._frame_handler = None
        self._read_buffer = b''
        self._closed = False
        self._current_chunk = None
        self._close_exc = None

    def _send_ack_or_nack(self, ack_or_nack: typing.Union[Ack, Nack]):
        if self._frame_handler is not None:
            self._frame_handler(ack_or_nack)

    def _notify_completion_handler(self):
        if self._completion_handler is not None:
            self._completion_handler(self._message_id, self.size(), self.bytes_left())

    def _close_nowait_with_exc(self, exc: Exception):
        if not self._closed:
            self._close_exc = exc
            if self._current_chunk is not None:
                self._send_ack_or_nack(Nack.from_chunk(self._current_chunk, b'Transfer terminated by peer'))
            self._notify_completion_handler()
            self._chunk_queue.put_nowait(None)
            self._closed = True

    @property
    def id(self):
        return self._message_id

    def register_completion_handler(self, func: typing.Callable[[int, int, int], None]):
        self._completion_handler = func

    def register_frame_handler(self, func: typing.Callable[[typing.Union[Ack, Nack]], None]):
        self._frame_handler = func

    def dispatch_chunk(self, chunk: Chunk):
        if chunk.message_id != self._message_id:
            return self._close_nowait_with_exc(jsi_exc.ProtocolError(f"got CHUNK with wrong message ID: {chunk}"))
        if chunk.message_size != self._swim_message_size:
            return self._close_nowait_with_exc(jsi_exc.ProtocolError(f"got CHUNK with wrong message size: {chunk}"))
        if self._current_chunk is not None:
            if self._current_chunk.index + 1 != chunk.index:
                return self._close_nowait_with_exc(jsi_exc.ProtocolError(f"got CHUNK with wrong index: {chunk}"))
        self._current_chunk = chunk
        if len(chunk.payload) > 0:
            self._chunk_queue.put_nowait(chunk)
        else:
            self._send_ack_or_nack(Ack.from_chunk(chunk))
            self._notify_completion_handler()

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        self._close_nowait_with_exc(StreamClosedError())

    def size(self) -> int:
        return self._real_message_size

    def bytes_left(self) -> int:
        return self._bytes_left

    async def read(self, count: int) -> bytes:
        if self._closed:
            raise self._close_exc
        if not self._read_buffer:
            chunk = await self._chunk_queue.get()
            if chunk is None:
                raise self._close_exc
            if chunk.index == 0:
                self._read_buffer += chunk.payload
            else:
                header_size, = struct.unpack("!I", chunk.payload[:4])
                self._read_buffer += chunk.payload[4 + header_size:]
            self._send_ack_or_nack(Ack.from_chunk(chunk))
        out = self._read_buffer[:count]
        self._read_buffer = self._read_buffer[count:]
        self._bytes_left -= len(out)
        if self._bytes_left == 0:
            self._notify_completion_handler()
        return out
